#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Check if exactly one argument is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <argument>\n", argv[0]);
        return 1;
    }

    // Get the length of the command-line argument
    size_t arg_length = strlen(argv[1]);

    // Allocate memory for the local buffer
    char *buffer = (char *)malloc(arg_length + 1);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Copy the command-line argument to the buffer
    strcpy(buffer, argv[1]);

    // Print the stored copy
    printf("Stored: %s\n", buffer);

    // Free the allocated memory
    free(buffer);

    return 0;
}
