```python
import subprocess
import os

def head_file(path, n):
    # Check if the path is a valid file
    if not os.path.isfile(path):
        raise FileNotFoundError(f"File not found: {path}")

    # Check if the number of lines requested is non-negative
    if n < 0:
        raise ValueError("Number of lines must be non-negative")

    # Use subprocess to run the head command
    try:
        result = subprocess.run(
            ["head", "-n", str(n), path],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        # Handle errors gracefully
        return f"Error: {e.stderr}"

# Example usage
if __name__ == "__main__":
    try:
        print(head_file("/path/to/your/file.txt", 5))
    except Exception as e:
        print(e)
