app = Flask(__name__)

@app.route('/logs')
def get_logs():
    file_path = request.args.get('file', default=None)

    if file_path is None:
        abort(400, description="Missing 'file' query parameter")

    file_path = f"./logs/{file_path}"

    try:
        with open(file_path, 'r') as file:
            # Seek to the end of the file and go back 10 lines
            file.seek(0, 2)
            file.seek(-10 * 1024, 1)  # 10 lines * 1024 bytes per line
            lines = file.readlines()
            return ''.join(lines)
    except FileNotFoundError:
        abort(404, description="File not found")

if __name__ == '__main__':
    app.run(debug=True)
