import os

def save_params(params, path):
    with open(path, 'w') as file:
        for layer_name, values in params.items():
            file.write(f"{layer_name}: ")
            file.write(", ".join(map(str, values)))
            file.write('\n')

def load_params(path):
    params = {}
    with open(path, 'r') as file:
        for line in file:
            line = line.strip()
            if line:
                layer_name, values_str = line.split(': ', 1)
                values = [float(val) for val in values_str.split(', ')]
                params[layer_name] = values
    return params
