import os

class SimpleFileCache:
    def __init__(self, cache_dir='./cache/'):
        # Ensure the cache directory exists
        if not os.path.exists(cache_dir):
            os.makedirs(cache_dir)
        self.cache_dir = cache_dir

    def cache_put(self, key, value):
        # Convert the value to a JSON-serializable format
        serialized_value = self._serialize(value)
        # Construct the full path for the cache file
        file_path = os.path.join(self.cache_dir, key)
        # Write the serialized value to the file
        with open(file_path, 'w') as file:
            file.write(serialized_value)

    def cache_get(self, key):
        # Construct the full path for the cache file
        file_path = os.path.join(self.cache_dir, key)
        # Check if the file exists
        if not os.path.exists(file_path):
            return None
        # Read the serialized value from the file
        with open(file_path, 'r') as file:
            serialized_value = file.read()
        # Deserialize the value
        return self._deserialize(serialized_value)

    def _serialize(self, value):
        # Convert the value to a JSON string
        return str(value)

    def _deserialize(self, serialized_value):
        # Convert the JSON string back to a Python value
        return eval(serialized_value)

# Example usage
cache = SimpleFileCache()
cache.cache_put('example_key', {'name': 'John', 'age': 30})
print(cache.cache_get('example_key'))  # Output: {'name': 'John', 'age': 30}
```

