#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_SIZE 1024

void read_username(char *out, size_t out_len) {
    char buffer[MAX_LINE_SIZE];
    size_t len = 0;

    // Read a line from standard input
    while (len < out_len - 1) {
        int c = getchar();
        if (c == EOF) {
            if (len > 0) {
                out[len] = '\0'; // Null-terminate the string
                return;
            } else {
                fprintf(stderr, "Error: No input provided.\n");
                exit(EXIT_FAILURE);
            }
        }
        buffer[len++] = c;

        // Check for newline character
        if (c == '\n') {
            buffer[len - 1] = '\0'; // Null-terminate the string
            break;
        }
    }

    // If buffer is not large enough, increase its size
    if (len == out_len - 1) {
        char *new_buffer = realloc(out, len + 2); // +2 for '\0' and possible additional characters
        if (new_buffer == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        out = new_buffer;
        out_len = len + 2;
    }

    // Ensure the string is null-terminated
    out[len] = '\0';

    // Remove trailing newline
    if (out[len - 1] == '\n') {
        out[len - 1] = '\0';
    }
}

